use crate::{DslValue,NativeDecodeControl,NativeReceiver,RetainedCloneGrant,RetainedCloneProgress,retained_clone::RetainedCloneSource,owned::tree::NativeScalarReceiver};
#[test]fn actual_native_owned_take_reports_its_own_work_and_no_work_for_denial_or_cached_output(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let initial=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let bank=std::cell::Cell::new(initial);let fuel=std::cell::Cell::new(s["fuel"].as_u64().unwrap());let post=|p:RetainedCloneProgress,work:u64|{let mut left=bank.get();assert!(p.fits(left));left.maximum_items-=p.copied_items;left.maximum_copy_bytes-=p.copied_bytes;left.maximum_capacity_bytes-=p.retained_capacity_bytes;left.maximum_release_bytes-=p.released_bytes;bank.set(left);fuel.set(fuel.get().checked_sub(work).unwrap());};let stock=initial;let mut source={let mut wallet=(&bank,&fuel);crate::source_fixture::capture(DslValue::Bool(law["value"].as_bool().unwrap()),&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.get().maximum_items.min(1),..w.0.get()},|w|w.1.get(),|_,p,work,_,_|post(p,work))};let mut receiver=NativeScalarReceiver::<DslValue,bool>::new();let mut callback=|_|true;let mut control=NativeDecodeControl::new(stock.maximum_capacity_bytes,&mut callback);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.output_ready(){break}let turn={let maximum=fuel.get();let grant=RetainedCloneGrant{maximum_items:bank.get().maximum_items.min(1),..bank.get()};crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(source.borrow(),control,4096,maximum,grant)})};let work=turn.work;let p=turn.result.unwrap().progress();post(p,work);}let(turn,heap)=crate::observe_retirement_allocations(||receiver.take(RetainedCloneGrant{maximum_items:0,..bank.get()}));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap());assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));let(turn,heap)=crate::observe_retirement_allocations(||receiver.take(RetainedCloneGrant{maximum_items:bank.get().maximum_items.min(1),..bank.get()}));assert_eq!(turn.work,law["takeWork"].as_u64().unwrap());let(value,p)=turn.result.unwrap().unwrap();assert_eq!(serde_json::to_value(value).unwrap(),law["value"]);assert_eq!(p.copied_bytes,law["copyBytes"].as_u64().unwrap()as usize);assert_eq!(heap,(0,0));post(p,turn.work);assert_eq!(receiver.take(Default::default()).work,law["cachedWork"].as_u64().unwrap());receiver.begin_close();let mut actual=None;for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,RetainedCloneGrant{maximum_items:bank.get().maximum_items.min(1),..bank.get()},fuel.get(),receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a));let work=turn.work;post(turn.result.unwrap().progress(),work);}assert!(receiver.terminal_is_empty());drop(receiver);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,RetainedCloneGrant{maximum_items:bank.get().maximum_items.min(1),..bank.get()},fuel.get(),source.next_close_demand(4096),source.next_close_work_demand(4096),|g,a|source.close_step(g,a));let work=turn.work;post(turn.result.unwrap().progress(),work);}assert!(source.terminal_is_empty());}

#[test]fn actual_native_sequence_owned_handoff_copies_no_retained_payload_and_keeps_denied_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];
 let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();
 fn post(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
 fn offer(bank:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:bank.maximum_items.min(1),..bank}}
 let values:Vec<bool>=serde_json::from_value(law["sequence"].clone()).unwrap();let input=DslValue::Array(values.iter().copied().map(DslValue::Bool).collect());let mut source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(input,&mut wallet,|w|offer(*w.0),|w|*w.1,|w,p,work,_,_|post(w.0,w.1,p,work))};
 let mut receiver=<Vec<bool>as crate::NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);
 for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.output_ready(){break}let turn={let maximum=fuel;let grant=offer(bank);crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(source.borrow(),control,4096,maximum,grant)})};let work=turn.work;post(&mut bank,&mut fuel,turn.result.unwrap().progress(),work);}assert!(receiver.output_ready());assert_eq!(receiver.take_demand().unwrap().copy_bytes,0);
 for g in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_depth:0,..bank}]{let(turn,heap)=crate::observe_retirement_allocations(||receiver.take(g));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));assert!(receiver.output_ready());}
 let(turn,heap)=crate::observe_retirement_allocations(||receiver.take(RetainedCloneGrant{maximum_copy_bytes:0,..offer(bank)}));assert_eq!(turn.work,1);let(output,p)=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,0);assert_eq!(heap,(0,0));assert_eq!(serde_json::to_value(&output).unwrap(),law["sequence"]);post(&mut bank,&mut fuel,p,turn.work);assert_eq!(receiver.take(Default::default()).work,0);
 let mut output=Some(output);let mut close=crate::retained_clone::RetainedCloneClose::default();let mut output_actual=None;for _ in 0..s["maximumTurns"].as_u64().unwrap(){if output.is_none()&&close.is_empty()&&output_actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut output_actual,offer(bank),fuel,close.next_owner_demands::<Vec<bool>>(output.is_some(),&None,4096),close.next_owner_work::<Vec<bool>>(output.is_some(),&None,4096),|g,a|if close.is_empty(){let turn=close.begin_granted(&mut output,g,a);crate::RetainedWorkOutcome{result:turn.result.map(|p|p.unwrap_or(crate::RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work}}else{close.step_granted(g,a)});let work=turn.work;post(&mut bank,&mut fuel,turn.result.unwrap().progress(),work);}assert!(output.is_none()&&close.is_empty());receiver.begin_close();let mut actual=None;for _ in 0..s["maximumTurns"].as_u64().unwrap(){if receiver.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,offer(bank),fuel,receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a));let work=turn.work;let step=turn.result.unwrap();if matches!(step,crate::RetainedCloneStep::Complete(_)){assert!(receiver.terminal_is_empty());}post(&mut bank,&mut fuel,step.progress(),work);}assert!(receiver.terminal_is_empty());drop(receiver);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if source.terminal_is_empty()&&actual.is_none(){break}let turn=crate::source_fixture::close_step(&mut actual,offer(bank),fuel,source.next_close_demand(4096),source.next_close_work_demand(4096),|g,a|source.close_step(g,a));let work=turn.work;post(&mut bank,&mut fuel,turn.result.unwrap().progress(),work);}assert!(source.terminal_is_empty());
}
